<?php
namespace App\Filament\Resources\Retakes;
use App\Filament\Resources\Retakes\Pages; use App\Models\Retake; use Filament\Actions\EditAction; use Filament\Forms\Components\DateTimePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table;
class RetakeResource extends Resource {
 protected static ?string $model=Retake::class; protected static ?string $modelLabel='пересдача'; protected static ?string $pluralModelLabel='Пересдачи'; protected static string|\UnitEnum|null $navigationGroup='Контроль успеваемости';
 public static function form(Schema $s): Schema{return $s->components([Select::make('academic_debt_id')->label('Задолженность')->relationship('debt','reason')->required()->searchable()->preload(),Select::make('student_id')->label('Студент')->relationship('student','last_name')->required()->searchable()->preload(),Select::make('discipline_id')->label('Дисциплина')->relationship('discipline','name')->required()->searchable()->preload(),Select::make('teacher_id')->label('Преподаватель')->relationship('teacher','last_name')->searchable()->preload(),TextInput::make('direction_number')->label('№ направления'),DateTimePicker::make('scheduled_at')->label('Дата и время'),TextInput::make('room')->label('Кабинет'),Select::make('status')->label('Статус')->options(['scheduled'=>'Назначена','completed'=>'Проведена','cancelled'=>'Отменена'])->default('scheduled')->required(),TextInput::make('grade')->label('Оценка')]);}
 public static function table(Table $t): Table{return $t->columns([TextColumn::make('direction_number')->label('Направление'),TextColumn::make('student.full_name')->label('Студент')->searchable(),TextColumn::make('discipline.name')->label('Дисциплина')->searchable(),TextColumn::make('scheduled_at')->label('Дата')->dateTime('d.m.Y H:i')->sortable(),TextColumn::make('room')->label('Кабинет'),TextColumn::make('status')->label('Статус')->badge(),TextColumn::make('grade')->label('Оценка')])->filters([SelectFilter::make('status')->label('Статус')->options(['scheduled'=>'Назначена','completed'=>'Проведена','cancelled'=>'Отменена'])])->recordActions([EditAction::make()]);}
 public static function getPages(): array{return ['index'=>Pages\ListRetakes::route('/'),'create'=>Pages\CreateRetake::route('/create'),'edit'=>Pages\EditRetake::route('/{record}/edit')];}
}